1	// THE TERMINAL TRANSITION, IN CODE (#892; tasks-dispatch DESIGN §6.5, §15.18,
2	// §15.19). A work-item session ends by performing five ordered side effects —
3	// comment, drop `task:agent`, add the outcome label, carry the execution record,
4	// close with the right state reason — and then releasing whatever the close
5	// freed. Asking a session to do that from prose is asking for it at the moment
6	// its context is fullest and the remaining work looks like formality; both of the
7	// first two live agentic runs got part of it wrong, silently, in different ways.
8	//
9	// The split is the same one the executor already draws: THE SESSION SUPPLIES THE
10	// JUDGMENT — which outcome, and the prose of what happened — and the CODE
11	// performs the transition. A session that stops early now leaves an item that is
12	// visibly unconverged, rather than one that looks finished and is not.
13	//
14	// Usage:
15	//   node converge-item.mjs --issue <n> --outcome <done|approval|action|decision|failure>
16	//                          --summary <text> [--pr <n>]
17	
18	import { pathToFileURL } from 'node:url';
19	import { renderTaskExec } from '../run-record.mjs';
20	import { readyDependents } from './readiness.mjs';
21	import {
22	  AGENT, NEEDS_HUMAN, TASK_DONE,
23	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_FAILURE,
24	  QUEUED_LABEL, IN_REVIEW_LABEL,
25	  hasLabel, parseWorkItemTitle, parseWorkItemBody,
26	} from './work-item.mjs';
27	
28	// What a session may claim, and what each one means for the item. `record` is the
29	// execution-record status, and `null` means no record: an approval park is a run
30	// that SUCCEEDED and left a PR, which the record vocabulary has no word for, and
31	// a fifth status would be stored data every decoder in the fleet must learn.
32	export const OUTCOMES = Object.freeze({
33	  done: { label: TASK_DONE, closes: true, stateReason: 'completed', record: 'success' },
34	  approval: { label: NEEDS_HUMAN_APPROVAL, closes: false, record: null },
35	  action: { label: NEEDS_HUMAN_ACTION, closes: false, record: 'failed' },
36	  decision: { label: NEEDS_HUMAN_DECISION, closes: false, record: 'failed' },
37	  failure: { label: NEEDS_HUMAN_FAILURE, closes: false, record: 'failed' },
38	});
39	
40	export function parseArgs(argv) {
41	  const args = {};
42	  for (let n = 0; n < argv.length; n += 1) {
43	    const m = /^--([a-z-]+)$/.exec(argv[n]);
44	    if (m) { args[m[1]] = argv[n + 1] ?? ''; n += 1; }
45	  }
46	  const issue = Number(args.issue);
47	  if (!Number.isInteger(issue) || issue <= 0) return { error: '--issue must be the work item\'s issue number' };
48	  if (!OUTCOMES[args.outcome]) {
49	    return { error: `--outcome must be one of ${Object.keys(OUTCOMES).join(', ')}, got ${JSON.stringify(args.outcome ?? null)}` };
50	  }
51	  if (!String(args.summary ?? '').trim()) return { error: '--summary must say what happened; it is the item\'s only durable account' };
52	  if (args.outcome === 'approval' && !args.pr) {
53	    return { error: '--pr must name the pull request an approval park is waiting on — a park nobody can act on is not a park' };
54	  }
55	  return { issue, outcome: args.outcome, summary: args.summary, pr: args.pr ? Number(args.pr) : null };
56	}
57	
58	// Why an item may NOT be converged by this call. Refusing loudly beats writing a
59	// terminal state onto the wrong issue: this runs from a session, whose whole
60	// notion of which item it holds came from an untrusted fire payload.
61	export function refusal(item, issue) {
62	  if (!item) return `#${issue} could not be read`;
63	  if (!parseWorkItemTitle(item.title ?? '')) return `#${issue} is not a Claudinite work item`;
64	  if (item.state !== 'open') return `#${issue} is already closed — it was converged once already`;
65	  if (!hasLabel(item, AGENT)) {
66	    return `#${issue} does not carry \`${AGENT}\` — this session does not hold it, so it is not this session's to converge`;
67	  }
68	  return null;
69	}
70	
71	// The record line for this item, or null where the vocabulary has no true answer.
72	export const recordLine = (item, status) => {
73	  const parsed = parseWorkItemTitle(item.title);
74	  return status && parsed
75	    ? renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })
76	    : null;
77	};
78	
79	// The comment one converge writes: the session's account, then the record, so a
80	// reader and a parser both find what they came for in one place.
81	export function convergeComment(item, { summary, pr, record }) {
82	  const rec = recordLine(item, record);
83	  const line = rec ? `\n\n\`\`\`\n${rec}\n\`\`\`` : '';
84	  const waiting = pr ? `\n\nWaiting on a person: merge or close #${pr}, then close this item.` : '';
85	  return `${summary.trim()}${waiting}${line}`;
86	}
87	
88	export async function convergeItem(api, gh, repo, plan, { now = () => new Date(), log = console.log } = {}) {
89	  const item = await api.readIssue(gh, repo, plan.issue);
90	  const no = refusal(item, plan.issue);
91	  if (no) return { ok: false, error: no };
92	
93	  const spec = OUTCOMES[plan.outcome];
94	  await api.comment(gh, repo, item.number, convergeComment(item, { ...plan, record: spec.record }));
95	  // The record goes to BOTH sinks, and neither is redundant: the comment is the
96	  // durable one (Actions logs expire, the item does not), while this printed copy
97	  // lands in the session transcript, which is what the usage fold reads for the
98	  // task-status census. The fold dedupes on the record's own tuple within a
99	  // capture file, so a line appearing in stdout and in the harness's echo of it
100	  // counts once.
101	  const rec = recordLine(item, spec.record);
102	  if (rec) log(rec);
103	  if (spec.closes) {
104	    await api.removeLabel(gh, repo, item.number, AGENT);
105	    await api.addLabel(gh, repo, item.number, spec.label);
106	    await api.closeIssue(gh, repo, item.number, spec.stateReason);
107	    // §15.19: whoever closes an item releases what it was holding.
108	    const freed = await readyDependents(api, gh, repo, item.number, { now, log });
109	    return { ok: true, closed: true, freed };
110	  }
111	  // Every park wears BOTH labels: `needs-human` is the state every guard and
112	  // sweep reads, the sub-label is what the person is being asked for.
113	  await api.swapLabel(gh, repo, item.number, AGENT, NEEDS_HUMAN);
114	  await api.addLabel(gh, repo, item.number, spec.label);
115	  // A REQUEST ITEM WRITES BACK TO ITS ISSUE, on the one end that is its business
116	  // (§16.5). Only the approval park: a failure deliberately writes nothing and
117	  // leaves `claude-queued` standing, because re-arming work that writes code is a
118	  // person's decision and that standing label is what stops the next scheduler run queueing
119	  // a second run of the same request.
120	  const { request } = parseWorkItemBody(item.body ?? '');
121	  if (request && plan.outcome === 'approval') {
122	    await api.comment(gh, repo, request,
123	      `A pull request for this is open and waiting on you: #${plan.pr}. Merge or close it.`);
124	    await api.swapLabel(gh, repo, request, QUEUED_LABEL, IN_REVIEW_LABEL);
125	  }
126	  return { ok: true, closed: false, freed: [], request: request ?? null };
127	}
128	
129	async function main() {
130	  const plan = parseArgs(process.argv.slice(2));
131	  if (plan.error) {
132	    console.error(`converge-item: ${plan.error}`);
133	    process.exit(2);
134	  }
135	  const { makeGh, actionRepoContext } = await import('../signals/gh.mjs');
136	  const api = await import('../github.mjs');
137	  const { repo } = actionRepoContext();
138	  if (!repo) { console.error('converge-item: GITHUB_REPOSITORY is not set'); process.exit(1); }
139	
140	  const res = await convergeItem(api, makeGh(), repo, plan);
141	  if (!res.ok) { console.error(`converge-item: ${res.error}`); process.exit(1); }
142	  console.log(res.closed
143	    ? `converged #${plan.issue}: closed ${OUTCOMES[plan.outcome].label}`
144	      + (res.freed.length ? `, released ${res.freed.map((n) => `#${n}`).join(', ')}` : '')
145	    : `converged #${plan.issue}: parked ${OUTCOMES[plan.outcome].label}, left open for a person`);
146	}
147	
148	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
149	  main().catch((e) => { console.error(e); process.exit(1); });
150	}
151

